PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE android_metadata (locale TEXT);
CREATE TABLE `patients` (`patientId` INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, `full_name` TEXT NOT NULL, `date_of_birth` INTEGER NOT NULL, `gender` TEXT NOT NULL, `phone_number` TEXT, `address` TEXT, `medical_record_number` TEXT NOT NULL, `created_at` INTEGER NOT NULL);
CREATE TABLE `medical_records` (`recordId` INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, `patient_id` INTEGER NOT NULL, `diagnosis` TEXT NOT NULL, `symptoms` TEXT NOT NULL, `disease_type` TEXT NOT NULL, `examination_date` INTEGER NOT NULL, `doctor_id` INTEGER NOT NULL, `notes` TEXT, `created_at` INTEGER NOT NULL, FOREIGN KEY(`patient_id`) REFERENCES `patients`(`patientId`) ON UPDATE NO ACTION ON DELETE CASCADE );
CREATE TABLE `doctors` (`doctorId` INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, `username` TEXT NOT NULL, `passwordHash` TEXT NOT NULL, `fullName` TEXT NOT NULL, `specialization` TEXT);
CREATE TABLE `appointments` (`appointmentId` INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, `record_id` INTEGER NOT NULL, `patientId` INTEGER NOT NULL, `appointment_date` INTEGER NOT NULL, `appointment_time` TEXT NOT NULL, `location` TEXT, `doctor_id` INTEGER NOT NULL, `notes` TEXT, `reminder_enabled` INTEGER NOT NULL, `reminder_time_before` INTEGER NOT NULL, `status` TEXT NOT NULL, `created_at` INTEGER NOT NULL, FOREIGN KEY(`record_id`) REFERENCES `medical_records`(`recordId`) ON UPDATE NO ACTION ON DELETE CASCADE );
CREATE TABLE `prescriptions` (`prescriptionId` INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, `record_id` INTEGER NOT NULL, `medicine_name` TEXT NOT NULL, `dosage` TEXT NOT NULL, `frequency` TEXT NOT NULL, `duration_days` INTEGER NOT NULL, `instructions` TEXT, `created_at` INTEGER NOT NULL, FOREIGN KEY(`record_id`) REFERENCES `medical_records`(`recordId`) ON UPDATE NO ACTION ON DELETE CASCADE );
CREATE TABLE room_master_table (id INTEGER PRIMARY KEY,identity_hash TEXT);
DELETE FROM sqlite_sequence;
CREATE INDEX `index_medical_records_patient_id` ON `medical_records` (`patient_id`);
CREATE UNIQUE INDEX `index_doctors_username` ON `doctors` (`username`);
CREATE INDEX `index_appointments_record_id` ON `appointments` (`record_id`);
CREATE INDEX `index_prescriptions_record_id` ON `prescriptions` (`record_id`);
COMMIT;